from ..objects.mosaiq_plan_promoting_objects import PlanPromoting
from interops.libraries.squish_actions import CommonActions

def __find_edit_site_setup_data_dialog() -> bool:
    """Searches for main Edit Site Setup Data Dialog. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the edit_course_data.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PlanPromoting.editSiteSetup_Data_Dialog) is not None else False

def __find_machine_location_ro_dialog() -> bool:
    """Searches for main Machine Location RO Dialog within the Edit Site Setup Dialog. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the edit_course_data.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PlanPromoting.editSiteSetup_Data_Machine_Location_RO_Dialog) is not None else False

def get_treatment_machine_id_setup_data() -> str:
    """Locates the Edit Site Setup Data Dialog UI > Locates the Treatment Machine ID row within the item list view and grabs all the child objects >
    returns the text value of the Treatment Machine ID Promote Data column.

    :raises RuntimeError: This raises if the Edit Site Setup Data Dialog UI isn't found.
    :return: String value of the Treatment Machine ID text value in the Promote Data column
    :rtype: str
    """
    if __find_edit_site_setup_data_dialog() is False:
        raise RuntimeError("Edit Site Setup Data Dialog was not open at the time get_treatment_machine_id_setup_data() was called.")
    treatment_machine_children = CommonActions.get_child_objects(PlanPromoting.editSiteSetup_Data_Treatment_Machine_ListViewItem)
    return CommonActions.get_objects_text_value(treatment_machine_children[2])

def set_treatment_machine_id_setup_data(treatmentMachine: str) -> None:
    """Locates the Edit Site Setup Data Dialog UI > Locates the Treatment Machine ID row within the item list view and grabs all the child objects >
    clicks the Treatment Machine ID textbox within the Promote Data column and locates the Machine Location RO Dialog UI that opens >
    selects the given treatmentMachine from the list view and confirms the selection.

    :raises RuntimeError: This raises if the Edit Site Setup Data Dialog UI isn't found.
    :return: String value of the Treatment Machine ID text value in the Promote Data column
    :rtype: str
    """
    if __find_edit_site_setup_data_dialog() is False:
        raise RuntimeError("Edit Site Setup Data Dialog was not open at the time set_treatment_machine_id_setup_data() was called.")
    treatment_machine_children = CommonActions.get_child_objects(PlanPromoting.editSiteSetup_Data_Treatment_Machine_ListViewItem)
    CommonActions.left_click_object(treatment_machine_children[2])

    if __find_machine_location_ro_dialog() is False:
        raise RuntimeError("Machine Location RO Dialog didn't open successfully when it was expected to be so.")

    CommonActions.press_key_sequence(treatmentMachine[0])
    found_machine_obj = CommonActions.get_child_object_by_object_text(
            objectList= CommonActions.get_child_objects(PlanPromoting.editSiteSetup_Data_Machine_Location_RO_ListView),
            searchText= treatmentMachine
        )
    CommonActions.left_click_object(found_machine_obj)
    CommonActions.left_click_object(PlanPromoting.editSiteSetup_Data_Machine_Location_RO_Select_Button)
    CommonActions.wait_for_object_to_disappear(PlanPromoting.editSiteSetup_Data_Machine_Location_RO_Dialog)
